typedef unsigned int nslSoundId;

struct os_developer_options {
    enum { FLAG_NO_AUDIO = 18 };
    char padding[0x48];
    int no_audio;
    static os_developer_options *inst();
    bool is_flagged(int) { return no_audio; }
};
extern os_developer_options *developer_options_instance;
asm(".equ developer_options_instance, 0x0046B180");
inline os_developer_options *os_developer_options::inst() { return developer_options_instance; }

void nslStopSound(nslSoundId);
asm(".equ nslStopSound__FUi, 0x0038D288");

struct FEMenuEntry {
    virtual ~FEMenuEntry();
    virtual bool GetDisable();
};

struct BeachData { int location; int main_beach; char padding[20]; };
struct BFE_Location { int levels[3]; int beaches[3]; int padding[2]; bool no_existing_levels; };
struct MapData { int west_east_order[26]; };

struct VOEngine { void setCurrentLevel(int); };
extern VOEngine VoiceOvers;
asm(".equ VoiceOvers, 0x0042F590");
asm(".equ setCurrentLevel__8VOEnginei, 0x00258558");

extern bool dampened;
asm(".equ dampened, 0x003E7718");

enum { BEACH_OPENSEA = 24, BEACH_LAST = 25, MAP_LOC_NOWHERE = -1 };

class BeachFrontEnd {
    char padding0[0x74];
    void *menu_vtable;
    char padding1[0x2f4 - 0x78];
    BeachData beaches[26];
    char padding2[0x5ac - 0x5cc];
    BFE_Location locations[17];
    char padding3[0x810 - 0x810];
    int current_beach_index;
    int current_level_index;
    int current_location_index;
    int cur_we_index;
    char padding4[0x894 - 0x820];
    FEMenuEntry *fe_return;
    FEMenuEntry *entry_list[26];
    int voiceOverStage;
    nslSoundId voiceOverSound;
    char padding5[0xee8 - 0x910];
    MapData map;
    char padding6[0xf0c - 0xf50];
    int in_career_mode;

    bool Realistic(bool);
    void setHigh(FEMenuEntry *entry)
    {
        char *table = *(char **)((char *)this + 0x74);
        short adjustment = *(short *)(table + 0x18);
        typedef void (*Call)(void *, FEMenuEntry *, bool);
        ((Call)*(void **)(table + 0x1c))((char *)this + adjustment, entry, true);
    }
public:
    FEMenuEntry *current;
    void SwitchBeach(bool right);
};
asm(".equ Realistic__13BeachFrontEndb, 0x00194120");

void BeachFrontEnd::SwitchBeach(bool right)
{
	dampened = false;
	if(!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		nslStopSound(voiceOverSound);
		voiceOverStage = 0;

	bool dis = false;
	bool same = false;
	bool nowhere = false;
	bool notabeach = false;

	do
	{
		cur_we_index += right ? 1 : -1;
		if(right && cur_we_index > BEACH_LAST) cur_we_index = 0;
		if(!right && cur_we_index < 0) cur_we_index = BEACH_LAST;
		if(cur_we_index != BEACH_LAST)
		{
			current_beach_index = map.west_east_order[cur_we_index];

			int loc = beaches[current_beach_index].location;
			dis = entry_list[current_beach_index]->GetDisable() && 
				(Realistic(false) || (in_career_mode && locations[loc].no_existing_levels) || current_beach_index == BEACH_OPENSEA);

			same = in_career_mode && beaches[current_beach_index].main_beach != -1;
			nowhere = beaches[current_beach_index].location == MAP_LOC_NOWHERE;
			notabeach = false;
		}
		else
		{
			notabeach = true;
			dis = true;
		}
	} while((!notabeach || dis) && (dis || same || nowhere));

	if (notabeach)
		current = fe_return;
	else 
		current = entry_list[current_beach_index];

	current_location_index = beaches[current_beach_index].location;
	current_level_index = locations[current_location_index].levels[0];
	setHigh(current);
	VoiceOvers.setCurrentLevel(current_level_index);
}
